// ═══════════════════════════════════════════════════════════════
// Extract Email Data - V3.3 (IMAP Simple + Targeted Mojibake Fix)
// Fix: regex-based — only operates on UTF-8-via-Latin-1 sequences
// See: https://github.com/n8n-io/n8n/issues/10230
// ═══════════════════════════════════════════════════════════════

const item = $input.item.json;

// Fix mojibake: only replace sequences that look like UTF-8 bytes misread as Latin-1
// [lead byte C0-F7] followed by [continuation bytes 80-BF]+
// Does NOT touch isolated chars like NBSP (\u00A0) or © (\u00A9)
function fixMojibake(text) {
  if (!text || typeof text !== 'string') return '';
  return text.replace(
    /[\xC0-\xF7][\x80-\xBF]+/g,
    match => Buffer.from(match, 'latin1').toString('utf8')
  );
}

const metadata = item.metadata || {};
const headers = {};

for (const [key, value] of Object.entries(metadata)) {
  if (typeof value === 'string') {
    headers[key.toLowerCase()] = value;
  }
}

if (item.from) headers['from'] = fixMojibake(item.from);
if (item.to) headers['to'] = item.to;
if (item.subject) headers['subject'] = fixMojibake(item.subject);
if (item.date) headers['date'] = item.date;

const textContent = fixMojibake((item.textPlain || '').trim());
const htmlContent = fixMojibake((item.textHtml || '').trim());

if (headers['subject']) headers['subject'] = fixMojibake(headers['subject']);

function stripHtml(html) {
  if (!html) return '';
  return html.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
}

const fullText = textContent + '\n' + stripHtml(htmlContent);
const subject = headers['subject'] || '';

return {
  json: {
    email_id: headers['message-id'] || null,
    thread_id: null,
    from: headers['from'] || null,
    to: headers['to'] || null,
    subject: subject,
    date: headers['date'] || new Date().toISOString(),
    body_text: textContent,
    body_html: htmlContent,
    headers: headers,
    full_text: (subject || '') + '\n\n' + fullText,
    attachments: [],
    has_attachments: false,
    attachment_count: 0
  }
};

// ═══════════════════════════════════════════════════════════════
// Prepare Payload for /ingest/raw - V5 (IMAP Provider-Agnostic)
// Reconstructs RFC822 from structured IMAP data for /ingest/raw
// ═══════════════════════════════════════════════════════════════

const emailData = $('Loop Over Items').first().json;
const tokenData = $input.first().json;
const token = tokenData.access_token;

// Reconstruct RFC822 from structured fields
// The backend /ingest/raw expects base64-encoded RFC822
const headers = emailData.headers || {};

let rfc822 = '';

// Build RFC822 headers
const headerOrder = [
  'from', 'to', 'subject', 'date', 'message-id',
  'in-reply-to', 'references', 'mime-version', 'content-type',
  'content-transfer-encoding', 'return-path', 'delivered-to',
  'received', 'received-spf', 'authentication-results',
  'dkim-signature', 'arc-seal', 'arc-message-signature',
  'arc-authentication-results'
];

// Add known headers in order
for (const key of headerOrder) {
  if (headers[key]) {
    const headerName = key.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join('-');
    rfc822 += headerName + ': ' + headers[key] + '\r\n';
  }
}

// Add any remaining headers not in the ordered list
for (const [key, value] of Object.entries(headers)) {
  if (!headerOrder.includes(key) && typeof value === 'string' && value.length < 2000) {
    const headerName = key.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join('-');
    rfc822 += headerName + ': ' + value + '\r\n';
  }
}

// Empty line separator
rfc822 += '\r\n';

// Body (prefer text, fallback to html)
if (emailData.body_text) {
  rfc822 += emailData.body_text;
} else if (emailData.body_html) {
  rfc822 += emailData.body_html;
}

// Encode to base64 for /ingest/raw
const rawSourceB64 = Buffer.from(rfc822, 'utf-8').toString('base64');

// Gmail account ID from fixtures
const accountId = '12b3f7b4-8fb1-4830-82d5-58d7fd874d2a';

// Extract threading headers
const inReplyTo = headers['in-reply-to'] || null;
const references = headers['references'] || null;
const messageId = headers['message-id'] || null;

const payload = {
  account_id: accountId,
  raw_source_rfc822_b64: rawSourceB64,
  ts_received: emailData.date || new Date().toISOString(),
  channel: 'email',
  rspamd: { score: 0, symbols: ['N8N'] },
  score_risk: 50,
  thread_id: null,                     // No thread concept with IMAP
  provider_msg_id: messageId,          // Use Message-ID as provider reference
  in_reply_to: inReplyTo,
  references: references,
  message_id: messageId,
  attachments: emailData.attachments || [],
  parsed: {
    headers: headers,
    body: {
      text: emailData.body_text || '',
      html: emailData.body_html || '',
      has_attachments: emailData.has_attachments || false,
      attachment_count: emailData.attachment_count || 0,
      text_length: (emailData.body_text || '').length,
      html_length: (emailData.body_html || '').length,
    }
  }
};

return {
  json: {
    token: token,
    payload: payload,
    email_id: emailData.email_id,
    full_text: emailData.full_text
  }
};

// Extract conv_id and msg_id from Ingest Email response
const ingestData = $('Ingest Email').first().json;
const riskData = $input.first().json;

return {
  json: {
    conv_id: ingestData.conv_id,
    last_msg_id: ingestData.msg_id,
    scam_category: riskData.category || 'Credential_phish',
    reason: 'auto_draft_on_inbound'
  }
};

const ingestData = $('Ingest Email').first().json;
const riskData = $('Get Risk Assessment').first().json;
return {
  json: {
    status: 'processed_no_reply',
    msg_id: ingestData.msg_id,
    conv_id: ingestData.conv_id,
    risk_level: riskData.risk_level,
    should_reply: riskData.should_reply,
    reply_generated: false,
    reason: 'Low risk, no exploitable artefacts',
    timestamp: new Date().toISOString()
  }
};

// ═══════════════════════════════════════════════════════════════
// Prepare for WF-ANALYZE-IOC - CORRECTED
// Purpose: Extract msg_id from backend response (NOT Gmail email_id)
// and prepare data for IOC extraction workflow
// ═══════════════════════════════════════════════════════════════

const ingestResponse = $('Ingest Email').first().json;
// const emailData = $('Extract Email Data').first().json;
const emailData = $('Loop Over Items').first().json;
const prepareData = $('Prepare Payload').first().json;

// IMPORTANT: Use backend msg_id (UUID), not Gmail email_id
// The backend message MUST exist before WF-ANALYZE-IOC runs
return {
  json: {
    msg_id: ingestResponse.msg_id,  // ← Backend UUID (REQUIRED by POST /iocs/enriched)
    body_text: emailData.body_text,
    subject: emailData.subject,
    headers: emailData.headers,
    full_text: prepareData.full_text
  }
};
